{"metadata":{"kernelspec":{"language":"python","display_name":"Python 3","name":"python3"},"language_info":{"pygments_lexer":"ipython3","nbconvert_exporter":"python","version":"3.6.4","file_extension":".py","codemirror_mode":{"name":"ipython","version":3},"name":"python","mimetype":"text/x-python"},"kaggle":{"accelerator":"none","dataSources":[],"isInternetEnabled":true,"language":"python","sourceType":"script","isGpuEnabled":false}},"nbformat_minor":4,"nbformat":4,"cells":[{"cell_type":"code","source":"# qa_bot.py\nimport os\nfrom transformers import pipeline\n\n# Load the question-answering pipeline with roberta-base-squad2 model \nmodel_name = \"deepset/roberta-base-squad2\"  \ndevice = 0  # Set to -1 for CPU or 0 for GPU\nqa_pipeline = pipeline(\"question-answering\", model=model_name, device=device)\n\n# Define a threshold for out-of-context detection\nCONFIDENCE_THRESHOLD = 0.6\n\n# Function to generate an answer or custom message if the question is out of context\ndef answer_question(question, context):\n    \"\"\"\n    Generate an answer based on a question and context, with handling for out-of-context questions.\n    \"\"\"\n    try:\n        # Use the QA pipeline to get the answer and confidence score\n        result = qa_pipeline(question=question, context=context)\n        \n        # Check the confidence score\n        if result['score'] < CONFIDENCE_THRESHOLD:\n            return \"I'm sorry, but that question seems unrelated to the provided context. Please try again.\"\n        \n        return result['answer']\n    \n    except Exception as e:\n        return f\"Error: {str(e)}\"\n","metadata":{"_uuid":"8f2839f25d086af736a60e9eeb907d3b93b6e0e5","_cell_guid":"b1076dfc-b9ad-4769-8c92-a6c4dae69d19","trusted":true},"outputs":[],"execution_count":null}]}